.vn{position:relative;height:100vh;height:100dvh;min-height:320px;overflow:hidden;background:#05070c;color:#f2f5fa;
  font-family:system-ui,-apple-system,"PingFang SC","Noto Sans CJK SC",sans-serif;user-select:none;
  --vn-safe-l:env(safe-area-inset-left,0px);--vn-safe-r:env(safe-area-inset-right,0px);
  --vn-safe-t:env(safe-area-inset-top,0px);--vn-safe-b:env(safe-area-inset-bottom,0px)}
.vn-bg{position:absolute;inset:0;background-size:cover;background-position:center;transition:opacity .45s ease}
.vn-vignette{position:absolute;inset:0;pointer-events:none;z-index:2;
  background:radial-gradient(ellipse at 50% 38%,transparent 38%,rgba(0,0,0,.55) 100%)}

/* ── 顶部 HUD：躲开状态栏 / 刘海 / 侧边导航栏 ── */
.vn-hud{position:absolute;z-index:7;display:flex;flex-wrap:wrap;gap:8px;align-items:center;
  top:calc(8px + var(--vn-safe-t));left:calc(12px + var(--vn-safe-l));right:calc(12px + var(--vn-safe-r))}
.vn-chip{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:999px;
  background:rgba(8,12,20,.6);border:1px solid rgba(255,255,255,.14);
  backdrop-filter:blur(8px);font-size:12px;letter-spacing:.04em}
.vn-chip b{font-weight:600}
.vn-chip i{width:6px;height:6px;border-radius:50%;background:#4fd6c8;display:inline-block}
.vn-chip-dim{opacity:.6}
.vn-hud-btn{padding:5px 13px;border-radius:999px;cursor:pointer;
  background:rgba(8,12,20,.6);border:1px solid rgba(255,255,255,.16);color:#e8eef8;
  font-size:12px;backdrop-filter:blur(8px)}
.vn-hud-btn:hover{background:rgba(30,44,64,.8)}

/* ── 立绘：三等分列，自动缩放，不参与点击 ── */
.vn-stage{position:absolute;inset:0;z-index:1;pointer-events:none;
  display:flex;align-items:flex-end;justify-content:space-between;padding:0 2%}
.vn-slot{flex:1 1 0;height:100%;display:flex;align-items:flex-end;justify-content:center;min-width:0}
.vn-sprite{display:block;max-width:100%;max-height:min(70vh,64vw);width:auto;height:auto;opacity:0;
  transition:opacity .35s ease,transform .35s ease;transform:translateY(12px);
  filter:drop-shadow(0 14px 28px rgba(0,0,0,.55))}
.vn-sprite.show{opacity:1;transform:translateY(0)}

/* ── 底部栈：选项 / 对话框 / 输入框 竖排，永不重叠 ── */
.vn-bottom{position:absolute;left:0;right:0;bottom:0;z-index:6;display:flex;flex-direction:column;gap:8px;
  padding:0 calc(14px + var(--vn-safe-r)) calc(10px + var(--vn-safe-b)) calc(14px + var(--vn-safe-l))}
.vn-bottom>*{width:100%;max-width:1080px;margin:0 auto}

.vn-choices{display:flex;flex-direction:column;gap:8px;max-height:40vh;overflow:auto;overscroll-behavior:contain}
.vn-choices[hidden]{display:none}
.vn-choice{padding:11px 16px;border-radius:10px;cursor:pointer;text-align:left;
  background:rgba(10,16,26,.9);border:1px solid rgba(255,255,255,.18);color:#eef3fb;
  font-size:14.5px;line-height:1.5;backdrop-filter:blur(10px);transition:all .18s ease}
.vn-choice:hover{background:rgba(46,86,132,.9);border-color:#7fb0e8}
.vn-choice:disabled{opacity:.42;cursor:not-allowed}
.vn-choice:disabled:hover{background:rgba(10,16,26,.9);border-color:rgba(255,255,255,.18)}

/* 状态提示条：等待回合 / 提交失败原因，直接摆在选项上方，避免“点了没反应”这种哑失败 */
.vn-notice{padding:8px 14px;border-radius:10px;font-size:12.5px;line-height:1.5;
  background:rgba(58,40,20,.88);border:1px solid rgba(255,190,110,.42);color:#ffd9a3}
.vn-notice[hidden]{display:none}

.vn-dialog{position:relative;min-height:104px;border-radius:12px;
  background:linear-gradient(180deg,rgba(8,12,22,.88),rgba(6,9,16,.95));
  border:1px solid rgba(255,255,255,.14);
  padding:16px 22px 22px;backdrop-filter:blur(12px);box-shadow:0 18px 44px rgba(0,0,0,.5)}
.vn-name{position:absolute;top:-13px;left:18px;padding:3px 14px;border-radius:999px;
  background:linear-gradient(135deg,#3a6ea5,#5b7fa6);font-size:13px;font-weight:700;letter-spacing:.06em;
  box-shadow:0 6px 16px rgba(0,0,0,.4)}
.vn-name:empty{display:none}
.vn-text{margin:4px 0 0;font-size:16.5px;line-height:1.9;letter-spacing:.02em;min-height:3.6em;white-space:pre-wrap}
.vn-advance{position:absolute;right:20px;bottom:6px;color:#8fb6e0;font-size:14px;
  animation:vn-bob 1.4s ease-in-out infinite;opacity:0}
.vn-advance.on{opacity:1}
@keyframes vn-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(4px)}}

.vn-input{display:flex;gap:8px}
.vn-input input{flex:1;min-width:0;padding:10px 14px;border-radius:9px;font-size:13.5px;
  background:rgba(8,12,20,.8);border:1px solid rgba(255,255,255,.14);color:#eaf0f8}
.vn-input input:focus{outline:none;border-color:#5b8fd0}
.vn-input button{padding:10px 22px;border-radius:9px;border:none;cursor:pointer;
  background:linear-gradient(135deg,#3a6ea5,#4f8fd0);color:#fff;font-size:13.5px;font-weight:600}

/* 消息镜像：宿主桥把消息渲染进 [data-tavern-messages]，我们只读它，不显示 */
.vn-mirror{position:absolute;left:-9999px;top:0;width:1px;height:1px;overflow:hidden;pointer-events:none}

.vn-log{position:absolute;left:50%;transform:translateX(-50%);top:6%;bottom:6%;width:min(88%,920px);z-index:9;
  border-radius:14px;padding:16px;background:rgba(6,9,16,.97);border:1px solid rgba(255,255,255,.16);overflow:auto}
.vn-log[hidden]{display:none}
.vn-log header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}
.vn-log header button{padding:4px 12px;border-radius:8px;cursor:pointer;
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);color:#dfe7f2;font-size:12px}
.vn-log-item{margin-bottom:12px;font-size:13.5px;line-height:1.7;color:#c8d4e4}
.vn-log-item b{color:#8fb6e0;display:block;font-size:12px;margin-bottom:2px;letter-spacing:.05em}

/* ── 矮横屏（手机横过来后 CSS 视口只有 ~360px 高）：整体收紧 ── */
@media (orientation:landscape) and (max-height:460px){
  /* 真机横屏：状态栏在顶部、三键导航栏在右侧；WebView 里 env() 可能为 0 → 用 max() 兜底 */
  .vn-hud{gap:6px;top:max(30px,calc(4px + var(--vn-safe-t)));
    left:max(12px,calc(10px + var(--vn-safe-l)));right:max(50px,calc(10px + var(--vn-safe-r)))}
  .vn-chip,.vn-hud-btn{padding:3px 9px;font-size:11px}
  .vn-bottom{gap:6px;
    padding:0 max(50px,calc(10px + var(--vn-safe-r))) calc(6px + var(--vn-safe-b)) max(12px,calc(10px + var(--vn-safe-l)))}
  .vn-notice{padding:6px 10px;font-size:11.5px}
  .vn-choices{gap:6px;max-height:36vh}
  .vn-choice{padding:7px 12px;font-size:12.5px;border-radius:8px}
  .vn-dialog{min-height:70px;padding:9px 14px 12px;border-radius:10px}
  .vn-name{top:-10px;left:12px;padding:2px 10px;font-size:11px}
  .vn-text{font-size:13px;line-height:1.6;min-height:2.6em}
  .vn-advance{right:14px;bottom:3px;font-size:12px}
  .vn-input input,.vn-input button{padding:7px 12px;font-size:12.5px}
  .vn-sprite{max-height:min(74vh,64vw)}
}

/* ── 竖屏降级：立绘收窄，底部栈占满 ── */
@media (orientation:portrait){
  .vn-sprite{max-height:52vh}
  .vn-text{font-size:15.5px}
}

