const root=document.getElementById('vn-root');if(!root)return;
const bgEl=document.getElementById('vn-bg'),nameEl=document.getElementById('vn-name'),
  textEl=document.getElementById('vn-text'),advEl=document.getElementById('vn-advance'),
  choicesEl=document.getElementById('vn-choices'),queueEl=document.getElementById('vn-queue'),
  locEl=document.getElementById('vn-loc'),noticeEl=document.getElementById('vn-notice');
const sprites={l:document.getElementById('vn-sprite-l'),c:document.getElementById('vn-sprite-c'),r:document.getElementById('vn-sprite-r')};
const state={queue:[],pending:[],typed:false,busy:false,timer:0,auto:false,log:[],bg:'雪夜林道',shown:{},sig:'',submitted:false,rev:undefined};
const AMP='&amp;',LT='&lt;',GT='&gt;',QUOT='&'+'quot;';
function escapeHtml(s){return String(s).replace(/[&<>"]/g,c=>c==='&'?AMP:c==='<'?LT:c==='>'?GT:QUOT);}
function setBg(name){if(!BG[name]||state.bg===name)return;state.bg=name;bgEl.style.opacity='0';
  setTimeout(()=>{bgEl.style.backgroundImage='url("'+BG[name]+'")';bgEl.style.opacity='1';},220);}
function setSprite(who){
  const d=CHARS[who];if(!d)return;
  const el=sprites[d.slot];if(!el)return;
  Object.keys(sprites).forEach(k=>{if(k!==d.slot)sprites[k].classList.remove('show');});
  if(el.getAttribute('src')!==d.src){el.setAttribute('src',d.src);el.classList.remove('show');}
  requestAnimationFrame(()=>el.classList.add('show'));
  state.shown={[d.slot]:who};
}
function pushLine(line){
  line=String(line==null?'':line);
  if(!line.trim())return;
  state.log.push(line);
  const m=line.match(/^([^：:\n]{1,8})[：:](.*)$/s);
  const hasName=m&&CHARS[m[1].trim()];
  state.queue.push({who:hasName?m[1].trim():'',text:(hasName?m[2]:line).trim()});
  const body=document.getElementById('vn-log-body');
  if(body){const d=document.createElement('div');d.className='vn-log-item';
    d.innerHTML=(hasName?'<b>'+escapeHtml(m[1].trim())+'</b>':'')+escapeHtml((hasName?m[2]:line).trim());
    body.appendChild(d);body.scrollTop=body.scrollHeight;}
  paintQueue();
}
function paintQueue(){
  if(!queueEl)return;
  if(state.queue.length){queueEl.textContent=state.queue.length+' 句待播';return;}
  queueEl.textContent=state.busy?'…':'待你选择';
}
/* 状态提示条：等待回合 / 提交失败原因 —— 别让玩家面对“点了没反应”这种哑失败 */
let noticeTimer=0;
function setNotice(text,ms){
  if(!noticeEl)return;
  clearTimeout(noticeTimer);
  if(!text){noticeEl.hidden=true;noticeEl.textContent='';return;}
  noticeEl.textContent=text;noticeEl.hidden=false;
  if(ms)noticeTimer=setTimeout(()=>{noticeEl.hidden=true;noticeEl.textContent='';},ms);
}
/* 把一段 AI 叙事 / Markdown 切成句子（galgame 的「逐句」来源） */
function splitSentences(text){
  return String(text==null?'':text)
    .replace(/```[\s\S]*?```/g,' ')
    .replace(/^#{1,6}\s*/gm,'').replace(/^[-*+]\s+/gm,'').replace(/^>\s*/gm,'')
    .replace(/\*\*(.+?)\*\*/g,'$1').replace(/[*_`]/g,'')
    .split(/(?<=[。！？!?…])\s*|\n{2,}/)
    .map(s=>s.trim()).filter(s=>s.length>1);
}
function typeLine(line){
  state.typed=false;state.busy=true;advEl.classList.remove('on');
  nameEl.textContent=line.who||'';
  nameEl.style.background=line.who&&CHARS[line.who]
    ?'linear-gradient(135deg,'+CHARS[line.who].color+',#2b3d55)':'';
  if(line.who)setSprite(line.who);
  const chars=[...line.text];let i=0;textEl.textContent='';
  clearInterval(state.timer);
  state.timer=setInterval(()=>{
    textEl.textContent+=chars[i++]||'';
    if(i>=chars.length){clearInterval(state.timer);state.typed=true;state.busy=false;advEl.classList.add('on');
      paintQueue();paintChoices();
      if(state.auto)setTimeout(()=>{if(state.auto)next();},900);}
  },26);
}
function next(){
  if(!state.typed&&textEl.textContent){ // 正在打字 → 先补全
    clearInterval(state.timer);state.typed=true;state.busy=false;advEl.classList.add('on');
    paintQueue();paintChoices();
    return;
  }
  if(!state.queue.length)return;
  typeLine(state.queue.shift());paintQueue();
}
