const OPENING=[
  '雪停了。林道两旁的落叶松挂满白霜，脚步声被雪吞掉，安静得不太正常。',
  '你：车辙到这里就断了。拉车的两匹马倒在路中央，货却一件没少。',
  '希尔达：「……别碰它们。」她从树后走出来，手套上全是血。「箭是从林子深处射的，射得极准。」',
  '贡德伦：「旅人，你总算追上了。」矮人蹲在车板旁敲了敲封蜡的木箱，「这车货，比两匹马的命值钱。」'
];
function boot(){
  bgEl.style.backgroundImage='url("'+BG[state.bg]+'")';
  OPENING.forEach(pushLine);
  paintQueue();
  next();
  /* 宿主已按 ui.shell.orientation 切方向，这里再兜一层（支持时才生效） */
  try{
    if(screen&&screen.orientation&&typeof screen.orientation.lock==='function'){
      screen.orientation.lock('landscape').catch(()=>{});
    }
  }catch(err){}
}
