root.addEventListener('click',e=>{
  const t=e.target;
  if(t.closest('button')||t.closest('input')||t.closest('.vn-log'))return;
  if(t.closest('.vn-choice'))return;
  next(); // 对话框 / 立绘 / 背景都能推进；选项摆着时也允许继续看完已入队的句子
});
document.getElementById('vn-auto')?.addEventListener('click',e=>{
  state.auto=!state.auto;
  const b=e.currentTarget;
  b.textContent=state.auto?'自动 ❚❚':'自动 ▸';
  if(state.auto)next();
});
document.getElementById('vn-log')?.addEventListener('click',()=>{
  const p=document.getElementById('vn-log-panel');if(p)p.hidden=false;
});
document.getElementById('vn-log-close')?.addEventListener('click',()=>{
  const p=document.getElementById('vn-log-panel');if(p)p.hidden=true;
});
