/* ── 宿主消息流 → 逐句播放 ──
   注意：宿主每次推送上下文都会 replaceChildren 重建消息 DOM，
   所以不能按节点身份去重（旧写法会让同一段文字反复入队 ⇒ 无限重播）。
   这里按「文本内容」去重；队列非空或正在打字时先挂起，绝不丢内容。 */
const seenText=new Set();
function ingest(){
  const stream=document.querySelector('[data-tavern-messages]');
  if(!stream)return;
  // 桥渲染的是 <article>；正文通常在里面，但纯文本消息可能没有子标签 → 兜底取 article 本身
  let nodes=[...stream.querySelectorAll('p,li,h1,h2,h3,blockquote')];
  if(!nodes.length)nodes=[...stream.querySelectorAll('article')];
  nodes.forEach(node=>{
    const t=node.textContent.trim();
    if(!t||t.length<2)return;
    if(seenText.has(t))return;
    seenText.add(t);
    if(state.queue.length||state.busy){state.pending.push(t);return;}
    splitSentences(t).forEach(s=>pushLine(s));
  });
  if(!state.queue.length&&!state.busy&&state.pending.length){
    splitSentences(state.pending.shift()).forEach(s=>pushLine(s));
  }
}
/* ── 选项：容器由宿主桥填充（button.tavern-option），我们只负责样式与显隐，绝不重建 DOM ── */
function paintChoices(){
  const box=choicesEl;if(!box)return;
  const btns=[...box.querySelectorAll('button,[data-tavern-option]')];
  btns.forEach(b=>{if(!b.classList.contains('vn-choice'))b.classList.add('vn-choice');});
  const sig=btns.map(b=>(b.textContent||'').trim()).join('|');
  if(!sig){box.hidden=true;state.sig='';state.submitted=false;return;}
  if(state.sig!==sig){state.sig=sig;state.submitted=false;} // 换了一组新选项 → 重新显示
  // 先看完这段文字再给选项：还有待播 / 正在打字时不出现
  const busy=state.queue.length>0||state.busy;
  box.hidden=busy||state.submitted;
}
// 点选项：不拦截、不改 DOM，交给桥自己的 click 处理；只把列表收起来
choicesEl&&choicesEl.addEventListener('click',e=>{
  if(!e.target.closest('button'))return;
  state.submitted=true;choicesEl.hidden=true;
});
/* 桥在元素上派发 tavern-input-error（不冒泡）⇒ 用捕获阶段接住，把失败原因显示出来 */
root.addEventListener('tavern-input-error',e=>{
  const msg=(e.detail&&e.detail.message)||'提交失败';
  setNotice('提交失败：'+msg,5000);
},true);
window.addEventListener('tavern-context',event=>{
  const d=event.detail||{};
  const loc=d.save&&d.save.state&&d.save.state.locationId;
  if(locEl&&loc)locEl.textContent=String(loc);
  if(/洞穴|矿|地底|矿坑/.test(String(loc||'')))setBg('地下暗河');
  else if(/酒馆|客栈|旅店|屋内/.test(String(loc||'')))setBg('酒馆内景');
  else setBg('雪夜林道');
  const rev=d.turn&&d.turn.revision;
  if(rev!==state.rev){state.rev=rev;state.submitted=false;} // 新回合 ⇒ 重新允许选择
  const canChoose=!(d.turn&&d.turn.canChoose===false);
  if(!canChoose)setNotice('等 AI 回应这一步…结束后才能再次行动',0);
  else setNotice('');
  ingest();paintChoices(); // 宿主每次推送上下文（含新选项）都立刻刷新
});
TavernExtension.on&&TavernExtension.on('turn.commit',()=>{setTimeout(ingest,260);});
TavernExtension.on&&TavernExtension.on('agent.complete',()=>{setTimeout(ingest,260);});
setInterval(()=>{ingest();paintChoices();},900);
boot();
}
